import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, float } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root group (adapter will set position/rotation/scale)
  const root = new Group();

  // ---------- Main backdrop plane ----------
  const backdropGeom = new PlaneGeometry(6.8, 2.0);
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = mix(color('#121218'), color('#0b0b10'), uv().y);
  backdropMat.roughnessNode = float(0.6);
  backdropMat.metalnessNode = float(0.2);
  backdropMat.transparent = true;
  backdropMat.opacity = 0;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  root.add(backdrop);

  // ---------- Top hairline rule ----------
  const hairGeom = new PlaneGeometry(6.8, 0.006);
  const hairMat = new MeshBasicNodeMaterial({ color: '#23232b' });
  hairMat.transparent = true;
  hairMat.opacity = 0;
  const hair = new Mesh(hairGeom, hairMat);
  hair.position.set(0, 1.0 - 0.003, 0.001);
  root.add(hair);

  // ---------- Left block (wordmark + accent) ----------
  const leftBlock = new Group();
  // block width 2.0, center offset from left edge (-3.4) = -3.4 + 1.0 = -2.4
  leftBlock.position.set(-3.4 + 1.0, 0, 0);
  // Wordmark
  const wordmark = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 34,
    color: '#16161d',
    align: 'left',
    letterSpacingPx: 0.02 * 34,
  });
  wordmark.position.set(-0.9, 0.25, 0);
  leftBlock.add(wordmark);
  // Accent bar
  const accentGeom = new PlaneGeometry(0.3, 0.02);
  const accentMat = new MeshStandardNodeMaterial();
  accentMat.emissiveNode = color('#ff2a38');
  accentMat.emissiveIntensity = 1.4;
  accentMat.transparent = true;
  accentMat.opacity = 0;
  const accent = new Mesh(accentGeom, accentMat);
  accent.position.set(0, -0.3, 0.001);
  leftBlock.add(accent);
  root.add(leftBlock);

  // ---------- Columns ----------
  const columnDefs = [
    {
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
    },
    {
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
    },
    {
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
    },
  ];

  const columnWidth = 1.2;
  const gutter = 0.375;
  const startX = -3.4 + 2.0 + gutter; // first column left edge
  const columnsGroup = new Group();

  columnDefs.forEach((col, idx) => {
    const colGroup = new Group();
    const colCenterX = startX + idx * (columnWidth + gutter) + columnWidth / 2;
    colGroup.position.set(colCenterX, 0, 0);

    // Header
    const header = ctx.fontAtlas.createText(col.header, {
      fontSize: 9,
      color: '#16161d',
      align: 'left',
      letterSpacingPx: 0.12 * 9,
    });
    header.position.set(-columnWidth / 2, 0.5, 0);
    colGroup.add(header);

    // Links
    col.links.forEach((linkText, i) => {
      const link = ctx.fontAtlas.createText(linkText, {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'left',
        letterSpacingPx: 0,
      });
      const yOffset = 0.5 - (i + 1) * 0.22; // line spacing approx
      link.position.set(-columnWidth / 2, yOffset, 0);
      // make material transparent for fade‑up
      link.traverse((obj) => {
        if (obj.material) {
          obj.material.transparent = true;
          obj.material.opacity = 0;
        }
      });
      // Hover handlers
      const hoverEnter = () => {
        gsap.to(link.position, { z: 0.02, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        link.traverse((obj) => {
          if (obj.material) {
            gsap.to(obj.material.color, {
              r: 1,
              g: 0.164,
              b: 0.22,
              duration: 0.14,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            });
          }
        });
      };
      const hoverLeave = () => {
        gsap.to(link.position, { z: 0, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        link.traverse((obj) => {
          if (obj.material) {
            gsap.to(obj.material.color, {
              r: 0.91,
              g: 0.93,
              b: 0.95,
              duration: 0.14,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            });
          }
        });
      };
      link.userData.handlers = {
        hover: { enter: hoverEnter, leave: hoverLeave },
      };
      colGroup.add(link);
    });

    columnsGroup.add(colGroup);
  });

  root.add(columnsGroup);

  // ---------- Legal line ----------
  const legalText = ctx.fontAtlas.createText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    {
      fontSize: 9,
      color: '#16161d',
      align: 'center',
      letterSpacingPx: 0.04 * 9,
    }
  );
  legalText.position.set(0, -0.9, 0);
  legalText.traverse((obj) => {
    if (obj.material) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
    }
  });
  root.add(legalText);

  // ---------- Fade‑up animation ----------
  const timelines = [];

  // make all meshes start transparent
  root.traverse((obj) => {
    if (obj.material) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
    }
  });

  const fadeTl = gsap.timeline();
  fadeTl.from(root.position, {
    y: 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  root.traverse((obj) => {
    if (obj.material) {
      fadeTl.to(
        obj.material,
        { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
        0
      );
    }
  });
  timelines.push(fadeTl);

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
